}

function stepToward(target) {
    const dx = target.x - player.x;
    const dy = target.y - player.y;
    if (Math.abs(dx) > Math.abs(dy)) {
        player.move(dx > 0 ? "right" : "left");
    } else {
        player.move(dy > 0 ? "down" : "up");
    }
}

function loop() {
    if (player.queued > 0) return;

    let target = world.bots()[0];

    if (!target) target = world.bots(20)[0];

    if (!target) return;

    if (Math.abs(target.x - player.x) + Math.abs(target.y - player.y) === 1) {
        player.attackClosest();
    } else {
        stepToward(target);
    }
}

function loop() {
    if (player.queued > 0) return;
    if (!world.wall(1, 0)) player.move("right");
    else if (!world.wall(0, 1)) player.move("down");
    else if (!world.wall(-1, 0)) player.move("left");
    else player.move("up");
}

